+#[test]
+fn the_posted_program_of_a_converted_tool_does_not_change() {
+    let (w, mut h) = shop();
+    let before = post(&w, "before");
+    h.execute(&w, ConvertToComponents::new(&w, &[SIX.to_owned()]).expect("convert"));
